// QR iteration for eigenvalues of a tridiagonal matrix.
// val = diagonal terms, o = squares of off-diagonal terms.
// On return val contains the eigenvalues (sorted ascending).
static void qriter(std::vector<double>& val, std::vector<double>& o, int n) {
    const double EPSI = 1.0e-10;
    const double ZERO = 0.0;
    const double ONE  = 1.0;

    int MAX = 100 * n;

    // 1-based indexing helpers: val[1..n], o[1..n-1]
    // We'll use vectors sized n+1 with index 0 unused.

    int M2 = n;

    while (true) {
        // Search for a decoupled submatrix.
        int M2M1 = M2 - 1;
        int M1 = 0;
        bool allZero = true;
        for (int k = 1; k <= M2M1; ++k) {
            M1 = M2 - k;
            if (o[M1] != ZERO) { allZero = false; break; }
        }
        if (allZero) {
            // all off-diagonal terms are zero, done
            break;
        }

        // Decoupled submatrix
        M2M1 = M1;
        M2   = M1 + 1;
        if (M2M1 != 1) {
            bool found = false;
            for (int k = 2; k <= M2M1; ++k) {
                M1 = M2 - k;
                if (o[M1] == ZERO) { found = true; break; }
            }
            if (found) M1 = M1 + 1;
        }
        int MM = M1;

        // QR iteration for the decoupled submatrix
        bool converged = false;
        for (int ITER = 1; ITER <= MAX; ++ITER) {
            if (std::abs(val[M2]) + o[M2M1] == std::abs(val[M2])) {
                converged = true;
                break;
            }
            // check if all val equal
